// TH15 v1.00b st01bs.ecl.txt::BossCard1 (source lines 408-481).
// Card frame 0 = source entry. The 120-frame shell buffer precedes the source timeline,
// so source local frame F runs at card frame 120+F.
// Source attack: two BossCard1_at2 async tasks start at source frame 94;
// BossCard1_at is spawned every 120+80 (E/N), 20+80 (H), 50+80 (L) source frames.

const TIME_LIMIT: int = 2524;      // 120 buffer + 2400 timerReset window + 4 startup margin
const OPENING_BUFFER: int = 120;

// TH15 synthetic bullet aliases (see transcribe/th15/touhou-bullets.ecl).
const TH15_ARROWHEAD: int = 544;   // source type 12, used by at2 SETSPRITE (color 2)
const TH15_BULLET: int = 560;      // source type 13 (BossCard1_at, color 6)
const TH15_BIG_BALL: int = 640;    // source type 18 (BossCard1_at2 birth look, color 3)

// Source at2 EX chain: ANIM/BRIGHT/SPEEDUP are birth/visual and omitted per TH15 policy.
// Behaviour kept: STEP type16 a=60 b=1 c=0 (linear decel 60f, then angle += r=+-90deg and
// restore the preserved speed), then SETSPRITE type12/color2.
// Target fires as TH15_ARROWHEAD so the long-lived radius is the source post-SETSPRITE 2.4;
// the source's first 60 frames are BIG_BALL (radius 8.5). Target keeps 2.4 throughout and
// only reproduces the big-ball look via set_sprite -> mismatch recorded in report.md.
xformdef AT2_STEP(spd: fx, turn_delta: angle) {
    set_sprite(TH15_BIG_BALL, 3);
    @60 step_speed(0fx, 60 + 65536 * EASE_LINEAR);
    set_speed(spd);
    turn(turn_delta);
    set_sprite(TH15_ARROWHEAD, 2);
}

// ---- source moveRand(60,4,1.0) recipe, retuned to moveLimit(0,128,240,64) ----
// shared slots: int0 = step count, fx0/fx1 = logical cos/sin of the chosen direction.
// Source inner direction zone is center +- width/4 = x +-60, y 112..144;
// actual position clamp is the full rectangle x [-120,120], y [96,160].
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    // source signed unit random * pi, kept as unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +-pi/2 guard, 0.05 rad (=522 BAM) around +-16384.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// ---- BossCard1_at(var A) ----
// etAim mode1 fixed-direction fan, base = ANGLE_PLAYER read at first run (source passes
// ANGLE_PLAYER but the argument A is unused; the etAngle read happens inside the async task).
// spacing 2deg = 364 BAM; volleys N=1..6 (E) / 1..8 (N,H,L); speed 1.5/2/3/4.
// Source bullet EX is only ANIM+SPEEDUP (birth/visual), omitted.
async sub at_shot() {
    var rank: int = global(GVAR_RANK);
    var spd: fx = 1.5fx;
    if rank == RANK_NORMAL { spd = 2fx; }
    else if rank == RANK_HARD { spd = 3fx; }
    else if rank == RANK_LUNATIC { spd = 4fx; }
    var volleys: int = 8;
    if rank == RANK_EASY { volleys = 6; }
    var gap: int = 4;
    if rank == RANK_EASY { gap = 6; }
    var base_i: int = aim_player() as int;
    var n: int = 1;
    for v in 0..volleys {
        for i in 0..n {
            var off: int = 0;
            if n % 2 == 0 {
                off = (i / 2) * 364 + 182;
            } else {
                off = ((i + 1) / 2) * 364;
            }
            if i % 2 != 0 { off = -off; }
            var ang_i: angle = (base_i + off) as angle;
            // source ANIM a=1 keeps position -= 4*velocity even though the birth stage is omitted.
            var back: fx = spd * 4fx;
            _ = fire(TH15_BULLET, 6, $self_x - back * cos(ang_i), $self_y - back * sin(ang_i),
                     spd, ang_i, none, none);
        }
        n = n + 1;
        wait(gap);
    }
}

// ---- BossCard1_at2(var A, var B) ----
// E/N/H: etAim mode1 fixed fan, base 90deg +- RANDF2*10deg (1820 BAM), spacing %C=30deg
// (5461 BAM), %C -= 2deg (364 BAM) after each cycle on N/H only.
// L: etAim mode3 fixed ring from base + i*65536/n; the second angle only rotates layers
// and M=1, so the 222.5deg source value has no geometric effect.
// Speed: E/N 1.5, H/L 2.0. Volleys: 6/20/40/60, wait 6/6/4/5. N caps at 16. 1000 cycles.
async sub at2(turn_delta: angle, spd: fx) {
    var rank: int = global(GVAR_RANK);
    var is_l: int = 0;
    if rank == RANK_LUNATIC { is_l = 1; }
    var volleys: int = 6;
    if rank == RANK_NORMAL { volleys = 20; }
    else if rank == RANK_HARD { volleys = 40; }
    else if rank == RANK_LUNATIC { volleys = 60; }
    var vwait: int = 6;
    if rank == RANK_HARD { vwait = 4; }
    else if rank == RANK_LUNATIC { vwait = 5; }
    var fan_delta: int = 5461;
    var cycles: int = 1000;
    while cycles > 0 {
        cycles = cycles - 1;
        var base_i: int = 16384 + ((rand(65536) - 32768) * 1820) / 32768;
        var n: int = 1;
        for v in 0..volleys {
            for i in 0..n {
                var off: int = 0;
                if is_l != 0 {
                    off = (i * 65536) / n;
                } else {
                    if n % 2 == 0 {
                        off = (i / 2) * fan_delta + fan_delta / 2;
                    } else {
                        off = ((i + 1) / 2) * fan_delta;
                    }
                    if i % 2 != 0 { off = -off; }
                }
                var ang_i: angle = (base_i + off) as angle;
                // source ANIM a=1 keeps position -= 4*velocity even though the birth stage is omitted.
                var back: fx = spd * 4fx;
                _ = fire(TH15_ARROWHEAD, 2, $self_x - back * cos(ang_i), $self_y - back * sin(ang_i),
                         spd, ang_i, AT2_STEP(spd, turn_delta), none);
            }
            if n < 16 { n = n + 1; }
            wait(vwait);
        }
        wait(130);
        if rank == RANK_NORMAL || rank == RANK_HARD {
            fan_delta = fan_delta - 364;
        }
    }
}

// ---- real boss (source Boss() entry state + BossCard1 lines 448-479) ----
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);              // source setHurtbox(40,40): circle radius 20
    set_hitbox(24fx);               // source setHitbox(48,48): circle radius 24
    set_self_int(0, 0);
    set_self_fx(0, 1fx);
    set_self_fx(1, 0fx);
    var rank: int = global(GVAR_RANK);
    var spd2: fx = 1.5fx;
    if rank >= RANK_HARD { spd2 = 2fx; }
    // source entry: +2 +2 then +90 at line 452 (movePosTime to (0,128) is already satisfied).
    wait(94);
    spawn at2(90deg, spd2);
    spawn at2(-90deg, spd2);
    var pre_wait: int = 120;
    if rank == RANK_HARD { pre_wait = 20; }
    else if rank == RANK_LUNATIC { pre_wait = 50; }
    var cycles: int = 1000;
    while cycles > 0 {
        cycles = cycles - 1;
        wait(pre_wait);
        card_move_rand();
        card_wait(80);
        spawn at_shot();
    }
    loop { wait(1); }
}

// ---- independent invulnerable training shell ----
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
